window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-cb1f8a1d25f0001b"]={"versions": [{"id": "FIG-cb1f8a1d25f0001b", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Konzeptionelles Struktur- und Konfigurationsdiagramm (UML-Objekt-/Metamodell-Abstraktion) der AUTOSAR Adaptive Platform (SWS Platform Health Management - PHM).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation der Mehrfachüberwachung von Checkpoints mittels <em>Alive Supervision</em> innerhalb einer einzelnen <code>SupervisedEntity</code> (<code>SE3</code>) für einen spezifischen Überwachungsmodus (<code>SupervisionMode</code>).\n</li><li><strong>Funktionale Einordnung:</strong> Das PHM realisiert die funktionale Sicherheitsüberwachung (ISO 26262) für Adaptive Applications. Die Alive-Supervision verifiziert zur Laufzeit, ob periodische Funktionen oder Threads innerhalb deterministischer zeitlicher Frequenzkorridore ausgeführt werden.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>SupervisedEntity</code> (<code>SE3</code>):</strong> \n<ul class=\"fig-list\"><li>Logische Gruppierungseinheit für sicherheitsrelevante Ausführungspfade innerhalb eines Prozesses der Adaptive Application.\n</li><li>Kapselt einen oder mehrere diskrete Überwachungspunkte.\n</li></ul>\n</li><li><strong><code>Checkpoint</code> (<code>CP3-1</code>, <code>CP3-2</code>):</strong>\n<ul class=\"fig-list\"><li>Eindeutig identifizierbare Kontrollpunkte im Applikationscode, die über die Schnittstelle <code>ara::phm::SupervisedEntity::ReportCheckpoint(CheckpointId)</code> getriggert werden.\n</li><li>Kardinalität: 1 : N zwischen <code>SupervisedEntity</code> und <code>Checkpoint</code>.\n</li></ul>\n</li><li><strong>Konfigurationsparameter je Checkpoint (Metamodell-Attribute):</strong>\n<ul class=\"fig-list\"><li><code>ExpectedAliveIndications</code>: Soll-Anzahl der Checkpoint-Meldungen innerhalb eines Bewertungsintervalls.\n</li><li><code>MinMargin</code>: Maximal zulässige negative Abweichung (Unterschreitung der Soll-Aufrufe).\n</li><li><code>MaxMargin</code>: Maximal zulässige positive Abweichung (Überschreitung der Soll-Aufrufe).\n</li><li><code>AliveReferenceCycle</code>: Länge des Referenzüberwachungsfensters (ausgedrückt in Zyklen des PHM-Auswertungstakts).\n</li><li><code>FailedReferenceCyclesTolerance</code>: Anzahl konsekutiv fehlerhafter Referenzzyklen, bevor ein Zustandstransfer nach <code>ALIVE_FAILED</code> bzw. <code>ALIVE_EXPIRED</code> ausgelöst wird.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Meldungsphase (Asynchron / Event-getrieben):</strong>\n<ul class=\"fig-list\"><li>Die Applikation durchläuft den Kontrollfluss und meldet das Erreichen von <code>CP3-1</code> bzw. <code>CP3-2</code> via IPC an den PHM-Daemon (<code>ReportCheckpoint</code>).\n</li></ul>\n</li><li><strong>Evaluierungsphase (Periodisch / Synchroner PHM-Zyklus):</strong>\n<ul class=\"fig-list\"><li>Jeder Checkpoint wird unabhängig voneinander nach Ablauf seines jeweiligen <code>AliveReferenceCycle</code> bewertet.\n</li><li>Gültigkeitsbedingung für einen fehlerfreien Zyklus:\n $$\\text{ExpectedAliveIndications} - \\text{MinMargin} \\le \\text{ActualIndications} \\le \\text{ExpectedAliveIndications} + \\text{MaxMargin}$$\n</li></ul>\n</li><li><strong>Fehlerakkumulation &amp; Statusübergang:</strong>\n<ul class=\"fig-list\"><li>Schlägt ein Zyklus fehl, wird der zyklische Fehlerzähler inkrementiert.\n</li><li>Überschreitet der Zähler <code>FailedReferenceCyclesTolerance</code>, degradiert der Alive-Status des betroffenen Checkpoints (<code>ALIVE_OK</code> → <code>ALIVE_FAILED</code>).\n</li><li>Der lokale Zustand der <code>SupervisedEntity</code> wird reevaluiert und fließt in die globale Zustandsmaschine des PHM ein (Auslösung konfigurierter Recovery-Aktionen via State Management / Execution Management).\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Unabhängige Parametrierung:</strong> \n<ul class=\"fig-list\"><li>Mehrere Checkpoints innerhalb derselben <code>SupervisedEntity</code> können disjunkte Ausführungsfrequenzen überwachen (z. B. <code>CP3-1</code> für eine 10-ms-Regelschleife, <code>CP3-2</code> für eine 100-ms-Diagnoseübertragung).\n</li></ul>\n</li><li><strong>Jitter &amp; Scheduling-Toleranz:</strong>\n<ul class=\"fig-list\"><li><code>MinMargin</code> und <code>MaxMargin</code> müssen unter Berücksichtigung von OS-Scheduling-Latenzen, Thread-Präemption und Ausführungs-Jitter gewählt werden, um False Positives zu verhindern.\n</li></ul>\n</li><li><strong>Konfigurationsbindung an <code>SupervisionMode</code>:</strong>\n<ul class=\"fig-list\"><li>Alive-Supervision-Parameter sind an den jeweiligen <code>SupervisionMode</code> gebunden. Bei Moduswechseln können Parametersätze ausgetauscht oder einzelne Checkpoints inaktiv geschaltet werden.\n</li></ul>\n</li><li><strong>API-Vertrag:</strong>\n<ul class=\"fig-list\"><li>Entwickler müssen sicherstellen, dass <code>ReportCheckpoint</code> nicht aus Interrupt-Kontexten mit blockierendem IPC aufgerufen wird und die übergebene <code>CheckpointId</code> exakt der im ARXML-Manifest deklarierten ID entspricht.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-59c7599c8228d09d", "releases": ["R22-11", "R23-11", "R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Konzeptionelles Struktur- und Konfigurationsdiagramm (UML-Objekt-/Metamodell-Abstraktion) der AUTOSAR Adaptive Platform (SWS Platform Health Management - PHM).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation der Mehrfachüberwachung von Checkpoints mittels <em>Alive Supervision</em> innerhalb einer einzelnen <code>SupervisedEntity</code> (<code>SE3</code>) für einen spezifischen Überwachungsmodus (<code>SupervisionMode</code>).\n</li><li><strong>Funktionale Einordnung:</strong> Das PHM realisiert die funktionale Sicherheitsüberwachung (ISO 26262) für Adaptive Applications. Die Alive-Supervision verifiziert zur Laufzeit, ob periodische Funktionen oder Threads innerhalb deterministischer zeitlicher Frequenzkorridore ausgeführt werden.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>SupervisedEntity</code> (<code>SE3</code>):</strong> \n<ul class=\"fig-list\"><li>Logische Gruppierungseinheit für sicherheitsrelevante Ausführungspfade innerhalb eines Prozesses der Adaptive Application.\n</li><li>Kapselt einen oder mehrere diskrete Überwachungspunkte.\n</li></ul>\n</li><li><strong><code>Checkpoint</code> (<code>CP3-1</code>, <code>CP3-2</code>):</strong>\n<ul class=\"fig-list\"><li>Eindeutig identifizierbare Kontrollpunkte im Applikationscode, die über die Schnittstelle <code>ara::phm::SupervisedEntity::ReportCheckpoint(CheckpointId)</code> getriggert werden.\n</li><li>Kardinalität: 1 : N zwischen <code>SupervisedEntity</code> und <code>Checkpoint</code>.\n</li></ul>\n</li><li><strong>Konfigurationsparameter je Checkpoint (Metamodell-Attribute):</strong>\n<ul class=\"fig-list\"><li><code>ExpectedAliveIndications</code>: Soll-Anzahl der Checkpoint-Meldungen innerhalb eines Bewertungsintervalls.\n</li><li><code>MinMargin</code>: Maximal zulässige negative Abweichung (Unterschreitung der Soll-Aufrufe).\n</li><li><code>MaxMargin</code>: Maximal zulässige positive Abweichung (Überschreitung der Soll-Aufrufe).\n</li><li><code>AliveReferenceCycle</code>: Länge des Referenzüberwachungsfensters (ausgedrückt in Zyklen des PHM-Auswertungstakts).\n</li><li><code>FailedReferenceCyclesTolerance</code>: Anzahl konsekutiv fehlerhafter Referenzzyklen, bevor ein Zustandstransfer nach <code>ALIVE_FAILED</code> bzw. <code>ALIVE_EXPIRED</code> ausgelöst wird.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Meldungsphase (Asynchron / Event-getrieben):</strong>\n<ul class=\"fig-list\"><li>Die Applikation durchläuft den Kontrollfluss und meldet das Erreichen von <code>CP3-1</code> bzw. <code>CP3-2</code> via IPC an den PHM-Daemon (<code>ReportCheckpoint</code>).\n</li></ul>\n</li><li><strong>Evaluierungsphase (Periodisch / Synchroner PHM-Zyklus):</strong>\n<ul class=\"fig-list\"><li>Jeder Checkpoint wird unabhängig voneinander nach Ablauf seines jeweiligen <code>AliveReferenceCycle</code> bewertet.\n</li><li>Gültigkeitsbedingung für einen fehlerfreien Zyklus:\n $$\\text{ExpectedAliveIndications} - \\text{MinMargin} \\le \\text{ActualIndications} \\le \\text{ExpectedAliveIndications} + \\text{MaxMargin}$$\n</li></ul>\n</li><li><strong>Fehlerakkumulation &amp; Statusübergang:</strong>\n<ul class=\"fig-list\"><li>Schlägt ein Zyklus fehl, wird der zyklische Fehlerzähler inkrementiert.\n</li><li>Überschreitet der Zähler <code>FailedReferenceCyclesTolerance</code>, degradiert der Alive-Status des betroffenen Checkpoints (<code>ALIVE_OK</code> → <code>ALIVE_FAILED</code>).\n</li><li>Der lokale Zustand der <code>SupervisedEntity</code> wird reevaluiert und fließt in die globale Zustandsmaschine des PHM ein (Auslösung konfigurierter Recovery-Aktionen via State Management / Execution Management).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Unabhängige Parametrierung:</strong> \n<ul class=\"fig-list\"><li>Mehrere Checkpoints innerhalb derselben <code>SupervisedEntity</code> können disjunkte Ausführungsfrequenzen überwachen (z. B. <code>CP3-1</code> für eine 10-ms-Regelschleife, <code>CP3-2</code> für eine 100-ms-Diagnoseübertragung).\n</li></ul>\n</li><li><strong>Jitter &amp; Scheduling-Toleranz:</strong>\n<ul class=\"fig-list\"><li><code>MinMargin</code> und <code>MaxMargin</code> müssen unter Berücksichtigung von OS-Scheduling-Latenzen, Thread-Präemption und Ausführungs-Jitter gewählt werden, um False Positives zu verhindern.\n</li></ul>\n</li><li><strong>Konfigurationsbindung an <code>SupervisionMode</code>:</strong>\n<ul class=\"fig-list\"><li>Alive-Supervision-Parameter sind an den jeweiligen <code>SupervisionMode</code> gebunden. Bei Moduswechseln können Parametersätze ausgetauscht oder einzelne Checkpoints inaktiv geschaltet werden.\n</li></ul>\n</li><li><strong>API-Vertrag:</strong>\n<ul class=\"fig-list\"><li>Entwickler müssen sicherstellen, dass <code>ReportCheckpoint</code> nicht aus Interrupt-Kontexten mit blockierendem IPC aufgerufen wird und die übergebene <code>CheckpointId</code> exakt der im ARXML-Manifest deklarierten ID entspricht.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-cb1f8a1d25f0001b", "to": "FIG-59c7599c8228d09d", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
